497		}
498	
499		// RAW and raw-other share only raw; the differently-cased names are distinct.
500		found := mustCommon(t, graph, "RAW", "raw-other")
501		if got, want := commonNames(found), []string{"raw"}; !reflect.DeepEqual(got, want) {
502			t.Fatalf("common sources = %v, want %v", got, want)
503		}
504		assertCommon(t, found, "raw", 1, []string{"raw", "RAW"}, 1, []string{"raw", "raw-other"})
505	}
506	
507	// A query never mutates the graph, and mutating returned records or paths can
508	// reach neither the graph, the other side's path, other records, nor later
509	// queries.
510	func TestCommonUpstreamsReadOnlyAndIsolated(t *testing.T) {
511		graph := buildRegisteredGraph(t, [][]string{
512			{"raw"},
513			{"a", "raw"},
514			{"b", "raw"},
515			{"x", "a"},
516			{"left", "a", "b"},
517			{"right", "b", "x"},
518		})
519		before := snapshot(graph)
520	
521		found, err := CommonUpstreams(graph, "left", "right")
522		if err != nil {
523			t.Fatalf("CommonUpstreams: %v", err)
524		}
525		if !reflect.DeepEqual(snapshot(graph), before) {
526			t.Fatalf("query changed graph: before=%v after=%v", before, snapshot(graph))
527		}
528	
529		// Abuse every returned slice, then confirm the graph and a repeat query are
530		// untouched and the two sides did not share storage.
531		found[0].PathToFirst[0] = "tampered-1"
532		found[0].PathToFirst = append(found[0].PathToFirst, "extra")
533		found[0].PathToSecond[0] = "tampered-2"
534		found[0].Dataset = "tampered"
535		found[0].DistanceToFirst = 99
536		found[0].DistanceToSecond = 99
537		if !reflect.DeepEqual(snapshot(graph), before) {
538			t.Fatalf("mutating results changed graph: before=%v after=%v", before, snapshot(graph))
539		}
540	
541		// A failed query is also read-only.
542		if _, err := CommonUpstreams(graph, "missing", "left"); err == nil {
543			t.Fatal("expected not-found error for first target")
544		}
545		if _, err := CommonUpstreams(graph, "left", "missing"); err == nil {
546			t.Fatal("expected not-found error for second target")
547		}
548		if !reflect.DeepEqual(snapshot(graph), before) {
549			t.Fatalf("failed queries changed graph: before=%v after=%v", before, snapshot(graph))
550		}
551		assertConsistent(t, graph)
552	
553		// A repeat query still returns the original, un-tampered content.
554		fresh := mustCommon(t, graph, "left", "right")
555		for _, c := range fresh {
556			for _, step := range append(append([]string(nil), c.PathToFirst...), c.PathToSecond...) {
557				if strings.Contains(step, "tampered") {
558					t.Fatalf("tampered path leaked into fresh query: %v", fresh)
559				}
560			}
561			if c.Dataset == "tampered" || c.DistanceToFirst == 99 || c.DistanceToSecond == 99 {
562				t.Fatalf("tampered record leaked into fresh query: %v", fresh)
563			}
564		}
565	}
566	
567	// A result taken before a re-registration keeps its original paths; only a
568	// re-query reflects the new edges.
569	func TestCommonUpstreamsOldResultStableAfterReregister(t *testing.T) {
570		graph := buildRegisteredGraph(t, [][]string{
571			{"raw"},
572			{"a", "raw"},
573			{"b", "raw"},
574			{"left", "a", "b"},
575			{"right", "a", "b"},
576		})
577	
578		before := mustCommon(t, graph, "left", "right")
579		beforeCopy := make([]CommonUpstream, len(before))
580		for i, c := range before {
581			beforeCopy[i] = CommonUpstream{
582				Dataset:          c.Dataset,
583				DistanceToFirst:  c.DistanceToFirst,
584				PathToFirst:      append([]string(nil), c.PathToFirst...),
585				DistanceToSecond: c.DistanceToSecond,
586				PathToSecond:     append([]string(nil), c.PathToSecond...),
587			}
588		}
589	
590		mustRegister(t, graph, "right", "a")
591		if !reflect.DeepEqual(before, beforeCopy) {
592			t.Fatalf("earlier result changed after re-register: before=%v snapshot=%v",
593				before, beforeCopy)
594		}
595	}
596	
597	// Every returned path starts with the source and ends at the queried target,
598	// and its length matches the reported distance plus one.
599	func TestCommonUpstreamsPathShape(t *testing.T) {
600		graph := buildRegisteredGraph(t, [][]string{
601			{"r"},
602			{"a", "r"},
603			{"b", "a"},
604			{"left", "b"},
605			{"x", "r"},
606			{"right", "x", "b"},
607		})
608	
609		found := mustCommon(t, graph, "left", "right")
610		for _, c := range found {
611			if c.PathToFirst[0] != c.Dataset || c.PathToFirst[len(c.PathToFirst)-1] != "left" {
612				t.Errorf("source %s path-to-first = %v must run from source to left", c.Dataset, c.PathToFirst)
613			}
614			if c.PathToSecond[0] != c.Dataset || c.PathToSecond[len(c.PathToSecond)-1] != "right" {
615				t.Errorf("source %s path-to-second = %v must run from source to right", c.Dataset, c.PathToSecond)
616			}
617			if len(c.PathToFirst) != c.DistanceToFirst+1 {
618				t.Errorf("source %s first path length %d != distance %d+1",
619					c.Dataset, len(c.PathToFirst), c.DistanceToFirst)
620			}
621			if len(c.PathToSecond) != c.DistanceToSecond+1 {
622				t.Errorf("source %s second path length %d != distance %d+1",
623					c.Dataset, len(c.PathToSecond), c.DistanceToSecond)
624			}
625		}
626	}
